-- STATUS: APPLIED 2026-08-04 against league_production
-- Restore the 739 play-stat identifiers the draft-only era falsifier wrongly NULLed.
--
-- League 8f4292e08 NULLed 739 nfl_play_stats.gsis_player_id values. Its era predicate consulted
-- only player.nfl_draft_year, and on a player row that merges two people the draft year belongs
-- to one of them while the career belongs to the other -- so the predicate rejected each row
-- against the wrong person.
--
-- A third falsifier settles it, independent of both date_of_birth and nfl_draft_year: the
-- gsis_player_id numeric block dates a player entry. For every one of the 13 ids below, the mean
-- nfl_draft_year of the players holding an adjacent serial (+/-40) matches the era of the plays
-- the id was removed from, and contradicts the draft year on the player row. 00-0031264 reads
-- 2014 against plays spanning 2014-2021 while its row says 2023; 00-0021142 reads 2002 against
-- plays spanning 2002-2009 while its row says 2022. Zero exceptions across 739 rows.
--
-- So every removed identifier was a correct statement about its own play. All 739 are restored,
-- not the 475 that the birth-date falsifier alone clears -- the other 264 are rows whose PLAYER
-- record is conflated, which is repaired on the player row and not by discarding feed data.
--
-- Keyed on (esbid, play_id, stat_id, player_name), which is the table's actual unique index
-- (idx_24719_play_stat). The three-column key is NOT unique: the 739 backup rows match 816 live
-- rows on it, so restoring through it would write 77 rows the backup never described.
--
-- Writes only where the column is currently NULL, so a value written since the repair is left
-- alone. Verified before running: all 739 match exactly and all 739 are NULL.
--
-- Restored from scratch/repair-name-match-misattribution/play-stats-gsis-before.json; the
-- per-player adjudication and its evidence are in that directory's adjudication.md.


CREATE TEMP TABLE play_stat_gsis_restore (
  esbid integer NOT NULL,
  play_id integer NOT NULL,
  stat_id integer NOT NULL,
  player_name varchar NOT NULL,
  gsis_player_id varchar NOT NULL
) ON COMMIT DROP;


-- Refuse the restore unless the backup still describes the live table exactly.
DO $$
DECLARE
  backup_count integer;
  matched_count integer;
  null_count integer;
BEGIN
  SELECT count(*) INTO backup_count FROM play_stat_gsis_restore;

  SELECT count(*) INTO matched_count
  FROM play_stat_gsis_restore r
  JOIN nfl_play_stats ps
    ON ps.esbid = r.esbid
   AND ps.play_id = r.play_id
   AND ps.stat_id = r.stat_id
   AND ps.player_name = r.player_name;

  SELECT count(*) INTO null_count
  FROM play_stat_gsis_restore r
  JOIN nfl_play_stats ps
    ON ps.esbid = r.esbid
   AND ps.play_id = r.play_id
   AND ps.stat_id = r.stat_id
   AND ps.player_name = r.player_name
  WHERE ps.gsis_player_id IS NULL;

  IF backup_count <> 739 THEN
    RAISE EXCEPTION 'backup carries % rows, expected 739', backup_count;
  END IF;

  IF matched_count <> backup_count THEN
    RAISE EXCEPTION 'backup matches % live rows, expected % -- the unique key is not holding',
      matched_count, backup_count;
  END IF;

  IF null_count <> backup_count THEN
    RAISE EXCEPTION '% of % target rows are already non-NULL -- something else has written here',
      backup_count - null_count, backup_count;
  END IF;
END $$;

UPDATE nfl_play_stats ps
SET gsis_player_id = r.gsis_player_id
FROM play_stat_gsis_restore r
WHERE ps.esbid = r.esbid
  AND ps.play_id = r.play_id
  AND ps.stat_id = r.stat_id
  AND ps.player_name = r.player_name
  AND ps.gsis_player_id IS NULL;

-- Player-row repair. The stat rows were never the defect; these are.
--
-- Ten rows where date_of_birth, the identifier and the career all agree and nfl_draft_year is the
-- lone intruder, corrected to the year the gsis cohort dates the identifier to. DEVI-TAYL-016049
-- is the eleventh and is deliberately absent: it is being split by a concurrent session
-- (repair-conflated-player-identity), and a field patch would collide with that split.
UPDATE player SET nfl_draft_year = 2014 WHERE pid = 'MAUR-ALEX-020348' AND nfl_draft_year = 2020;
UPDATE player SET nfl_draft_year = 2015 WHERE pid = 'JORD-WILL-021812' AND nfl_draft_year = 2022;
UPDATE player SET nfl_draft_year = 2019 WHERE pid = 'JOHN-LOVE-025414' AND nfl_draft_year = 2022;
UPDATE player SET nfl_draft_year = 2009 WHERE pid = 'MICH-BROW-000997' AND nfl_draft_year = 2021;
UPDATE player SET nfl_draft_year = 2003 WHERE pid = 'ERIC-POWE-020982' AND nfl_draft_year = 2006;
UPDATE player SET nfl_draft_year = 2002 WHERE pid = 'MARK-MART-016413' AND nfl_draft_year = 2012;
UPDATE player SET nfl_draft_year = 2002 WHERE pid = 'TODD-FRAN-014736' AND nfl_draft_year = 2005;
UPDATE player SET nfl_draft_year = 2007 WHERE pid = 'JEDX-COLL-021417' AND nfl_draft_year = 2011;
UPDATE player SET nfl_draft_year = 2016 WHERE pid = 'MIKE-ROSE-003617' AND nfl_draft_year = 2022;
UPDATE player SET nfl_draft_year = 2003 WHERE pid = 'CORE-MCIN-011679' AND nfl_draft_year = 2005;

-- MALI-WILL-013192 is the one genuine identifier theft. dob 1999-01-14, drafted 2022, Appalachian
-- State, currently on BUF -- every field but this one describes a live modern player, while
-- 00-0021142 is a 2002-era id whose plays run 2002-2009. Clear the false claim rather than
-- synthesizing a replacement, per the a966d7fbd precedent.
UPDATE player SET gsis_player_id = NULL
WHERE pid = 'MALI-WILL-013192' AND gsis_player_id = '00-0021142';

